(35711, 'Acts 6:1', 'Acts', 6, 1, 'په هغو ورځو کې چې د عیسی د پیروانو شمېر زیاتېده، نو یوناني ژبو یهودیانو د عبراني ژبو یهودیانو څخه شکایت وکړ چې د ورځني خوراک د وېشلو په وخت کې یوناني ژبو یهودي کونډو ښځو ته خپله برخه نه ورکول کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts6_verse_1.mp3', '', 1761754199, 1761754199),
(35712, 'Acts 6:2', 'Acts', 6, 2, 'نو هغو دولسو رسولانو ټول ایمانداران راوغوښتل او ویې ویل: «دا زمونږ دپاره مناسبه نه ده چې نورو ته د خوړو د رسولو په خاطر خلکو ته د خدای د پیغام رسول پرېږدو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts6_verse_2.mp3', '', 1761754199, 1761754199),
(35713, 'Acts 6:3', 'Acts', 6, 3, 'نو ای خویندو او ورونو! د خپل منځ څخه اووه تنه چې نېک نامه او د روح القدس څخه ډک او د حکمت لرونکي خلک وي غوره کړئ، ترڅو د دې کارونو مسوولیت د هغوی په غاړه واچوو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts6_verse_3.mp3', '', 1761754199, 1761754199),
(35714, 'Acts 6:4', 'Acts', 6, 4, 'خو مونږ به خپل وخت په دعا کولو او د خدای د کلام په وعظ او تعلیم ورکولو تېروو.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts6_verse_4.mp3', '', 1761754199, 1761754199),
(35715, 'Acts 6:5', 'Acts', 6, 5, 'د رسولانو دا نظر د ټولو خوښ شو، نو هغوی استیفان چې ډېر ایمانداره سړی ؤ او د روح القدس څخه ډک ؤ او فیلیپوس، پروکروس، نیکانور، تیمون، پرمیناس او نیکولاوس چې یهودي شوی ؤ او د سوریې د انطاکیې څخه ؤ، غوره کړل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts6_verse_5.mp3', '', 1761754199, 1761754199),
(35716, 'Acts 6:6', 'Acts', 6, 6, 'هغوی دا کسان رسولانو ته وروپېژندل او رسولانو د هغوی په سرونو باندې خپل لاسونه کېښودل او د هغوی دپاره یې دعا وکړه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts6_verse_6.mp3', '', 1761754199, 1761754199),
(35717, 'Acts 6:7', 'Acts', 6, 7, 'نو د خدای کلام په پرله پسې توګه خپرېده او په اورشلیم کې د ایماندارانو شمېر زیاتېده او ډېرو کاهنانو هم ایمان راوړ. د استیفان نیول', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts6_verse_7.mp3', '', 1761754199, 1761754199),
(35718, 'Acts 6:8', 'Acts', 6, 8, 'استیفان چې د خدای د فضل او قدرت څخه ډک ؤ، د خلکو په منځ کې به یې ډېر حیرانوونکي کارونه کول او معجزې به یې ښودلې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts6_verse_8.mp3', '', 1761754199, 1761754199),
(35719, 'Acts 6:9', 'Acts', 6, 9, 'خو ځینې خلک چې د ازادو خلکو په نوم د کنیسې غړي وو چې د قیروان او سکندریې د ښارونو او نور خلک چې د قیلیقیې او اسیا د ولایتونو څخه وو، راپورته شول او د استیفان سره یې بحث پیل کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts6_verse_9.mp3', '', 1761754199, 1761754199),
(35720, 'Acts 6:10', 'Acts', 6, 10, 'خو استیفان داسې په حکمت او د روح القدس په قدرت سره خبرې کولې چې هغوی نه شو کولای د هغه په وړاندې ودریږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts6_verse_10.mp3', '', 1761754199, 1761754199),
(35721, 'Acts 6:11', 'Acts', 6, 11, 'نو هغوی ځینې خلک ولمسول چې ووایي: «مونږ واورېدل چې استیفان د موسی او خدای په ضد کفر ویل.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts6_verse_11.mp3', '', 1761754199, 1761754199),
(35722, 'Acts 6:12', 'Acts', 6, 12, 'نو په دې ډول هغوی خلک، مشران او د شریعت عالمان راوپارول او استیفان یې ونیوه او شورا ته یې راوست.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts6_verse_12.mp3', '', 1761754199, 1761754199),
(35723, 'Acts 6:13', 'Acts', 6, 13, 'بیا هغوی څو تنه د دروغو شاهدان راوستل او دې شاهدانو وویل: «دا سړی تل د دې سپېڅلي کور او د موسی د شریعت په خلاف خبرې کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts6_verse_13.mp3', '', 1761754199, 1761754199),
(35724, 'Acts 6:14', 'Acts', 6, 14, 'مونږ د هغه څخه واورېدل چې ویل یې: ‹ناصري عیسی به دا د خدای کور وران کړي او کوم دودونه او دستورونه چې موسی مونږ ته راکړي دي هغه به بدل کړي.›»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts6_verse_14.mp3', '', 1761754199, 1761754199),
(35725, 'Acts 6:15', 'Acts', 6, 15, 'نو په شورا کې چې کوم خلک ناست وو هغوی ټولو په ځیر سره استیفان ته کتل او ویې لیدل چې د هغه مخ لکه د فرښتې د مخ په شان ځلېده.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/acts6_verse_15.mp3', '', 1761754199, 1761754199),
(35726, 'Colossians 3:1', 'Colossians', 3, 1, 'نو څنګه چې تاسو د مسیح سره په روحاني توګه راژوندي شوي یئ، بیا د هغو شیانو په لټه کې اوسئ چې په اسمان کې دي، یعنې په هغه ځای کې چې مسیح د خدای ښي لاس ته ناست دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_1.mp3', '', 1761754199, 1761754199),
(35727, 'Colossians 3:2', 'Colossians', 3, 2, 'د هغو شیانو په هکله فکر کوئ چې په اسمان کې دي، نه د هغو شیانو په هکله چې په دنیا کې دي،', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_2.mp3', '', 1761754199, 1761754199),
(35728, 'Colossians 3:3', 'Colossians', 3, 3, 'ځکه چې تاسو مړه شوي یئ او ستاسو ژوند د مسیح سره په خدای کې پټ دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_3.mp3', '', 1761754199, 1761754199),
(35729, 'Colossians 3:4', 'Colossians', 3, 4, 'کله چې مسیح چې ستاسو ژوندون دی، راښکاره شي، نو تاسو به هم د هغه سره په جلال کې ښکاره شئ. زوړ فطرت او نوی فطرت', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_4.mp3', '', 1761754199, 1761754199),
(35730, 'Colossians 3:5', 'Colossians', 3, 5, 'نو له دې امله دنیاوي غوښتنې لکه جنسي بد‌اخلاقي، ناپاکي، شهوت‌پرستي، بدې غوښتنې او حرص چې بت‌پرستي ده، په خپل ځان کې له منځه یوسئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_5.mp3', '', 1761754199, 1761754199),
(35731, 'Colossians 3:6', 'Colossians', 3, 6, 'د همدې شیانو له امله د خدای غضب په هغو خلکو باندې نازلیږي چې نافرمانه وي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_6.mp3', '', 1761754199, 1761754199),
(35732, 'Colossians 3:7', 'Colossians', 3, 7, 'تاسو هم په خپل تېر ژوند کې په همدې لارو تللئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_7.mp3', '', 1761754199, 1761754199),
(35733, 'Colossians 3:8', 'Colossians', 3, 8, 'خو اوس تاسو باید د هر ډول قهر، غضب او بدۍ نه لاس واخلئ او تهمت او بدې خبرې دې ستاسو د خولې نه راونه وځي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_8.mp3', '', 1761754199, 1761754199),
(35734, 'Colossians 3:9', 'Colossians', 3, 9, 'یو بل ته دروغ مه وایئ، ځکه چې تاسو خپل زوړ فطرت او د هغه ټول بد عملونه د خپل وجود نه لېرې کړي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_9.mp3', '', 1761754199, 1761754199),
(35735, 'Colossians 3:10', 'Colossians', 3, 10, 'تاسو د نوي فطرت لباس اغوستی دی او نور هم زیات د خپل خالق په شان شوي یئ چې هغه ښه وپېژنئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_10.mp3', '', 1761754199, 1761754199),
(35736, 'Colossians 3:11', 'Colossians', 3, 11, 'نو بیا د غیریهودي او یهودي، سنت شوي او ناسنته، وروسته پاتې او وحشي، غلام او ازاد ترمنځ فرق نشته، بلکې مسیح هرڅه دی او په مونږ ټولو کې دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_11.mp3', '', 1761754199, 1761754199),
(35737, 'Colossians 3:12', 'Colossians', 3, 12, 'نو بیا تاسو چې د خدای غوره شوي یئ، سپېڅلي او په خدای باندې ګران یئ، نو د زړه سواندۍ، مهربانۍ، عاجزۍ، نرمۍ او صبر کالي واغوندئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_12.mp3', '', 1761754199, 1761754199),
(35738, 'Colossians 3:13', 'Colossians', 3, 13, 'یو بل وزغمئ او که چېرې د یو بل نه کومه ګیله او شکایت لرئ، یو بل وبخښئ، لکه څنګه چې څښتن تاسو بخښلي یئ نو همداسې تاسو یو بل وبخښئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_13.mp3', '', 1761754199, 1761754199),
(35739, 'Colossians 3:14', 'Colossians', 3, 14, 'د ټولو نه مهمه دا ده چې یو بل سره ډېره مینه وکړئ، ځکه چې مینه هرڅه په پوره یووالي کې یو د بل سره یوځای کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_14.mp3', '', 1761754199, 1761754199),
(35740, 'Colossians 3:15', 'Colossians', 3, 15, 'نو پرېږدئ چې هغه سوله او سلامتي چې د مسیح له خوا راځي، ستاسو په زړونو حکومت وکړي، ځکه تاسو هر یو د مسیح د بدن غړي یئ او په دې خاطر غوره شوي یئ، ترڅو یو د بل سره په سوله کې ژوند وکړئ او شکرګزاره اوسئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_15.mp3', '', 1761754199, 1761754199),
(35741, 'Colossians 3:16', 'Colossians', 3, 16, 'پرېږدئ چې د مسیح کلام په پوره توګه په تاسو کې اوسي. په ټول حکمت سره یو بل ته تعلیم او نصیحت وکړئ او د زړه له کومې خپلو زړونو کې په شکرګزارۍ سره خدای ته زبورونه، مذهبي او روحاني سندرې ووایئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_16.mp3', '', 1761754199, 1761754199),
(35742, 'Colossians 3:17', 'Colossians', 3, 17, 'تاسو چې هرڅه کوئ، که هغه خبرې وي یا کوم کار وي، نو ټول د څښتن عیسی په نوم یې کوئ او د هغه په وسیله د پلار خدای شکر وباسئ. په کورنۍ کې د یو مسیحي مسوولیت', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_17.mp3', '', 1761754199, 1761754199),
(35743, 'Colossians 3:18', 'Colossians', 3, 18, 'ای ښځو، د خپلو مېړونو تابعدارې اوسئ، ځکه چې د څښتن د پیروانو په توګه دا کار تاسو ته مناسب دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_18.mp3', '', 1761754199, 1761754199),
(35744, 'Colossians 3:19', 'Colossians', 3, 19, 'ای مېړونو، د خپلو ښځو سره مینه کوئ او د هغوی سره بد چلند مه کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_19.mp3', '', 1761754199, 1761754199),
(35745, 'Colossians 3:20', 'Colossians', 3, 20, 'ای اولادونو، په هر کار کې د خپل مور او پلار منونکي اوسئ، ځکه چې په دې څښتن خوشحالیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_20.mp3', '', 1761754199, 1761754199),
(35746, 'Colossians 3:21', 'Colossians', 3, 21, 'ای پلرونو، د خپلو اولادونو قهر مه راپاروئ، هسې نه چې زړونه یې تور شي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_21.mp3', '', 1761754199, 1761754199),
(35747, 'Colossians 3:22', 'Colossians', 3, 22, 'ای غلامانو، په هرڅه کې د خپلو دنیاوي بادارانو تابعداري کوئ، یوازې هغه وخت نه چې کله هغوی تاسو څاري او تاسو هغوی خوشحاله کوئ، بلکې د زړه د اخلاصه او د خدای له وېرې د هغوی تابعداري کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_22.mp3', '', 1761754199, 1761754199),
(35748, 'Colossians 3:23', 'Colossians', 3, 23, 'تاسو چې هر کار کوئ هغه د زړه له کومي وکړئ، لکه څنګه چې تاسو یې د څښتن دپاره کوئ، نه د انسان دپاره.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_23.mp3', '', 1761754199, 1761754199),
(35749, 'Colossians 3:24', 'Colossians', 3, 24, 'ځکه تاسو پوهېږئ چې څښتن به د دې په اجر کې تاسو ته میراث درکړي او په دې خاطر تاسو د څښتن مسیح خدمت کوئ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_24.mp3', '', 1761754199, 1761754199),
(35750, 'Colossians 3:25', 'Colossians', 3, 25, 'نو بدکاره به د خپلې بدۍ سزا وویني، ځکه چې خدای د هېچا طرفداري نه کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/colossians3_verse_25.mp3', '', 1761754199, 1761754199),
(35751, 'Revelation 11:1', 'Revelation', 11, 1, 'بیا یې ماته د اندازه کولو یو لرګی راکړ او راته ویې ویل: «لاړ شه او د خدای د کور او د قربانۍ د ځای اندازه واخله او عبادت کوونکي وشمېره.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation11_verse_1.mp3', '', 1761754199, 1761754199),
(35752, 'Revelation 11:2', 'Revelation', 11, 2, 'خو د خدای د کور باندېنۍ حوېلۍ مه اندازه کوه. هغه پرېږده، ځکه چې هغه بې‌ایمانه خلکو ته ورکړل شوې ده او هغوی به دا سپېڅلی ښار تر دوه څلوېښتو میاشتو پورې تر پښو لاندې کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation11_verse_2.mp3', '', 1761754199, 1761754199),
(35753, 'Revelation 11:3', 'Revelation', 11, 3, 'زه به خپلو دوه شاهدانو ته چې د ویر کالي یې اغوستي دي، واک او اختیار ورکړم او هغوی به د یو زرو دوه سوه شپېتو ورځو په موده کې د خدای پیغام خلکو ته رسوي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation11_verse_3.mp3', '', 1761754199, 1761754199),
(35754, 'Revelation 11:4', 'Revelation', 11, 4, 'دا دوه شاهدان د زیتون دوه ونې او دوه څراغدانونه دي چې د ځمکې د خاوند په حضور کې ولاړ دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation11_verse_4.mp3', '', 1761754199, 1761754199),
(35755, 'Revelation 11:5', 'Revelation', 11, 5, 'که څوک وغواړي هغوی ته زیان ورسوي، نو د هغوی د خولې نه به اور راووځي او خپل دښمنان به وسوځوي. په دې ډول هرڅوک چې وغواړي هغوی ته زیان ورسوي، وژل کیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation11_verse_5.mp3', '', 1761754199, 1761754199),
(35756, 'Revelation 11:6', 'Revelation', 11, 6, 'هغوی دا واک او اختیار لري چې اسمان بند کړي ترڅو په هغه وخت کې چې هغوی د خدای پیغام خلکو ته رسوي، باران ونه شي. همدارنګه هغوی دا واک او اختیار لري چې اوبه په وینو بدلې کړي او هر وخت چې وغواړي په ځمکه باندې هر ډول بلا راولي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation11_verse_6.mp3', '', 1761754199, 1761754199),
(35757, 'Revelation 11:7', 'Revelation', 11, 7, 'کله چې هغوی خپله شاهدي ورکول سرته ورسوي، نو هغه ځناور چې د ځمکې د تل څخه راوځي، هغه به د هغوی سره جنګ وکړي او هغوی ته به ماتې ورکړي او وبه یې وژني.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation11_verse_7.mp3', '', 1761754199, 1761754199),
(35758, 'Revelation 11:8', 'Revelation', 11, 8, 'د هغوی مړي به په هماغه لوی ښار کې چې د هغوی څښتن په کې په صلیب باندې ځړول شوی ؤ، په کوڅو کې پراته وي. دا ښار په روحاني توګه د سدوم او مصر په نوم یادیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation11_verse_8.mp3', '', 1761754199, 1761754199),
(35759, 'Revelation 11:9', 'Revelation', 11, 9, 'تر درې نیمو ورځو پورې به د هر قوم، هرې قبیلې، هرې ژبې او هر ملت خلک د هغوی مړو ته ګوري او هېچا ته به اجازه نه ورکول کیږي چې هغوی ښخ کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation11_verse_9.mp3', '', 1761754199, 1761754199),
(35760, 'Revelation 11:10', 'Revelation', 11, 10, 'د ځمکې په مخ ټول خلک به هغوی پورې خاندي، خوشحالي به کوي، جشن به نیسي او یو بل ته به سوغاتونه ورکوي، ځکه چې دغو دواړو پیغمبرانو هغوی ډېر په عذاب کړي وو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation11_verse_10.mp3', '', 1761754199, 1761754199),
(35761, 'Revelation 11:11', 'Revelation', 11, 11, 'خو د درې نیمو ورځو نه وروسته خدای په هغوی کې د ژوندون روح واچاوه او هغوی په خپلو پښو ودرېدل او کومو خلکو چې هغوی ولیدل، ډېر ووېرېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation11_verse_11.mp3', '', 1761754199, 1761754199),
(35762, 'Revelation 11:12', 'Revelation', 11, 12, 'بیا هغو دوه پیغمبرانو د اسمان نه یو لوړ اواز واورېد چې هغوی ته یې ویل: «دلته پورته راشئ!» او په داسې حال کې چې دښمنانو یې ورته کتل، هغوی په ورېځو کې اسمان ته وختل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation11_verse_12.mp3', '', 1761754199, 1761754199),
(35763, 'Revelation 11:13', 'Revelation', 11, 13, 'په هماغه وخت کې یوه سخته زلزله وشوه او د هغه ښار لسمه برخه راوغورځېدله او اووه زره کسان په دې زلزله کې مړه شول او پاتې کسان ډېر ووېرېدل او د اسمانونو خدای ثنا یې ویله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation11_verse_13.mp3', '', 1761754199, 1761754199),
(35764, 'Revelation 11:14', 'Revelation', 11, 14, 'دوهمه بلا تېره شوه، خو درېمه بلا به زر راشي. اووم سرنی', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation11_verse_14.mp3', '', 1761754199, 1761754199),
(35765, 'Revelation 11:15', 'Revelation', 11, 15, 'بیا اوومې فرښتې خپل سرنی وواهه او په اسمان کې لوړ اوازونه واورېدل شول چې ویل یې: د نړۍ پاچاهي زمونږ د څښتن خدای او د هغه د مسیح شوه او هغه به تل ترتله پاچاهي کوي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation11_verse_15.mp3', '', 1761754199, 1761754199),
(35766, 'Revelation 11:16', 'Revelation', 11, 16, 'بیا هغه څلورویشت مشران چې د خدای په حضور کې په خپلو تختونو باندې ناست وو، په ځمکه باندې پړمخې پرېوتل او د خدای عبادت یې وکړ', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation11_verse_16.mp3', '', 1761754199, 1761754199),
(35767, 'Revelation 11:17', 'Revelation', 11, 17, 'او ویل یې: ای مطلق قادر څښتنه خدایه! کوو ستا شکر چې ته یې او وې ځکه چې تا په لاس کې واخیست خپل لوی قدرت او تا شروع کړه پاچاهي', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation11_verse_17.mp3', '', 1761754199, 1761754199),
(35768, 'Revelation 11:18', 'Revelation', 11, 18, 'شول په قهر ولسونه او قومونه ځکه وخت رارسېدلی ستا د قهر رارسېدلی هغه وخت چې قضاوت وشي د مړو په هکله او رارسېدلی هغه وخت چې اجر ورکړل شي ستا خدمتګارانو یعنې پیغمبرانو، سپېڅلو او هغو خلکو ته چې وېریږي ستا د نوم نه که هغه لوی وي یا کوچني رارسېدلی دی اوس وخت د تباهۍ د هغو خلکو تباه کوله یې چې ځمکه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation11_verse_18.mp3', '', 1761754199, 1761754199),
(35769, 'Revelation 11:19', 'Revelation', 11, 19, 'بیا په اسمان کې د خدای کور پرانیستل شو او د هغه په کور کې د هغه د لوظ صندوق ولیدل شو. برېښنا وځلېدله، د تندر غږ شو، غړمبار شو، زلزله وشوه او سخته ږلۍ وورېدله.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/revelation11_verse_19.mp3', '', 1761754199, 1761754199),
(35770, 'Romans 9:1', 'Romans', 9, 1, 'زه د مسیح سره تړاو لرم، نو رښتیا وایم او دروغ نه وایم. زما وجدان چې د روح القدس تابعداري کوي، د دې شاهد دی', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans9_verse_1.mp3', '', 1761754199, 1761754199),
(35771, 'Romans 9:2', 'Romans', 9, 2, 'چې زما په زړه کې د خپل قوم یعنې یهودیانو په خاطر چې زما خپلوان دي ډېر لوی غم او نه‌ختمېدونکی خفګان دی.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans9_verse_2.mp3', '', 1761754199, 1761754199),
(35772, 'Romans 9:3', 'Romans', 9, 3, 'د هغوی دپاره زه په دې هیله وم چې لعنتي شم او د مسیح نه بېل شم.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans9_verse_3.mp3', '', 1761754199, 1761754199),
(35773, 'Romans 9:4', 'Romans', 9, 4, 'هغوی اسراییلیان دي او هغوی ته د خدای اولادونه ویل شوي دي او جلال، لوظونه، شریعت، د عبادت مراسم او وعدې ورکړل شوي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans9_verse_4.mp3', '', 1761754199, 1761754199),
(35774, 'Romans 9:5', 'Romans', 9, 5, 'زمونږ نیکونه یعنې ابراهیم، اسحاق او یعقوب هم د هغوی سره تړاو لري او مسیح په انساني لحاظ د هغوی د نسل څخه دی. خدای چې په ټولو باندې حکومت کوي، هغه ته دې تل ترتله ثنا وي. امین.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans9_verse_5.mp3', '', 1761754199, 1761754199),
(35775, 'Romans 9:6', 'Romans', 9, 6, 'دا په دې معنی نه ده چې د خدای کلام خپل مقصد ته نه دی رسېدلی. ځکه چې ټول اسراییلیان د خدای غوره شوي خلک نه دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans9_verse_6.mp3', '', 1761754199, 1761754199),
(35776, 'Romans 9:7', 'Romans', 9, 7, 'او نه هم د ابراهیم ټول نسل د خدای اولادونه دي. ځکه چې خدای ابراهیم ته وویل: «ستا نسل به د اسحاق څخه حساب شي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans9_verse_7.mp3', '', 1761754199, 1761754199),
(35777, 'Romans 9:8', 'Romans', 9, 8, 'مقصد دا چې هغه ټول اولادونه چې په جسماني لحاظ د ابراهیم د نسل څخه پیدا شوي دي، د خدای اولادونه نه ګڼل کیږي، بلکې یوازې هغوی د خدای په اولادونو کې حسابیږي چې د خدای د وعدې له مخې پیدا شوي دي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans9_verse_8.mp3', '', 1761754199, 1761754199),
(35778, 'Romans 9:9', 'Romans', 9, 9, 'ځکه چې د خدای وعده داسې وه: «کله چې زه په راتلونکي کال کې په همدې وخت بېرته راشم، نو ساره به زوی ولري.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans9_verse_9.mp3', '', 1761754199, 1761754199),
(35779, 'Romans 9:10', 'Romans', 9, 10, 'یوازې دا نه، بلکې ربکا د یو کس نه چې هغه زمونږ نیکه اسحاق دی، امیدواره شوه.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans9_verse_10.mp3', '', 1761754199, 1761754199),
(35780, 'Romans 9:11', 'Romans', 9, 11, '‏-۱۲ خو د دې دپاره چې د خدای مقصد د دې غبرګونکو څخه د یو په غوره کولو کې پوره شي، نو خدای ربکې ته وویل: «مشر زوی به د کشر خدمت کوي.» هغه دا خبره د هغوی د زېږېدلو نه مخکې وکړه او مخکې له دې چې هغوی کوم ښه یا بد کار وکړي. ترڅو دا وښایي چې د خدای غوره کېدل د هغه د بلنې له مخې وو، نه د هغوی د عملونو له مخې.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans9_verse_11.mp3', '', 1761754199, 1761754199),
(35781, 'Romans 9:13', 'Romans', 9, 13, 'لکه څنګه چې د خدای په کلام کې لیکل شوي دي: یعقوب راباندې ګران ؤ، خو عیسو مې رد کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans9_verse_13.mp3', '', 1761754199, 1761754199),
(35782, 'Romans 9:14', 'Romans', 9, 14, 'نو بیا مونږ څه ووایو؟ ووایو چې خدای بې‌انصافه دی؟ هېڅکله نه!', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans9_verse_14.mp3', '', 1761754199, 1761754199),
(35783, 'Romans 9:15', 'Romans', 9, 15, 'ځکه چې خدای موسی ته وویل: «زه چې په هرچا باندې وغواړم رحم وکړم، نو رحم ورباندې کوم او په هرچا باندې چې وغواړم زړه وسوځوم، نو زړه ورباندې سوځوم.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans9_verse_15.mp3', '', 1761754199, 1761754199),
