(35796, 'Romans 9:28', 'Romans', 9, 28, 'ځکه څښتن به د ټولو خلکو په باره کې به په پوره توګه او زر د ځمکې په مخ خپل قضاوت تر‌سره کړي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans9_verse_28.mp3', '', 1761754199, 1761754199),
(35797, 'Romans 9:29', 'Romans', 9, 29, 'او لکه څنګه چې اشعیا مخکې پېشګویي کړې وه: که مونږ ته مطلق قادر څښتن نسلونه پریښي نه وای، نو مونږ به د سدوم او عمورې په شان تباه شوي وای. د اسراییلو بې‌ایماني', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans9_verse_29.mp3', '', 1761754199, 1761754199),
(35798, 'Romans 9:30', 'Romans', 9, 30, 'نو بیا مونږ څه ووایو؟ که څه هم غیریهودیانو کوښښ نه کاوه چې د خدای په نظر کې عادلان وګڼل شي، خو هغه یې د ایمان په وسیله تر‌لاسه کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans9_verse_30.mp3', '', 1761754199, 1761754199),
(35799, 'Romans 9:31', 'Romans', 9, 31, 'خو اسراییلیانو چې کوښښ کاوه د شریعت په وسیله عادلان وګڼل شي، نو هغه یې تر‌لاسه نه کړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans9_verse_31.mp3', '', 1761754199, 1761754199),
(35800, 'Romans 9:32', 'Romans', 9, 32, 'ځکه چې د هغوی کوښښ د ایمان له لارې نه، بلکې د هغوی د خپلو عملونو په بنیاد ؤ. نو هغوی په هغې ښویېدونکې تیږې باندې وښویېدل.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans9_verse_32.mp3', '', 1761754199, 1761754199),
(35801, 'Romans 9:33', 'Romans', 9, 33, 'لکه څنګه چې د خدای په کلام کې لیکل شوي دي: ګورئ، زه په صهیون کې یوه داسې تیږه ږدم چې د خلکو د ښویېدلو سبب شي او یو داسې ګټ چې هغوی پرې ولویږي. خو هرڅوک چې په هغه باندې ایمان راوړي، نو هېڅکله به ونه شرمیږي.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/romans9_verse_33.mp3', '', 1761754199, 1761754199),
(35802, 'John 5:1', 'John', 5, 1, 'له هغې نه وروسته عیسی د یهودیانو د اختر په خاطر اورشلیم ته لاړ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_1.mp3', '', 1761754199, 1761754199),
(35803, 'John 5:2', 'John', 5, 2, 'په اورشلیم کې هغه ځای ته نژدې چې د پسونو د دروازې په نوم یادېده یو ډنډ دی چې په آرامي ژبه کې ورته بیت‌حسدا وایي او پنځه دالانونه لري.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_2.mp3', '', 1761754199, 1761754199),
(35804, 'John 5:3', 'John', 5, 3, 'په دې دالانونو کې زیات شمېر ناروغه خلک چې ړانده، ګوډان او شلان وو، پراته وو. [هغوی دې ته انتظار کاوه', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_3.mp3', '', 1761754199, 1761754199),
(35805, 'John 5:4', 'John', 5, 4, 'چې په ډنډ کې اوبه خوځیږي. ځکه کله کله به د خدای فرښته دې ډنډ ته کوزېدله او اوبه به یې روانولې او هغه څوک چې به د ټولو نه مخکې ډنډ ته ښکته کېده نو د هر مرض نه به روغېده.]', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_4.mp3', '', 1761754199, 1761754199),
(35806, 'John 5:5', 'John', 5, 5, 'هلته یو سړی ؤ چې د اته دېرشو کالو راهیسې شل ؤ.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_5.mp3', '', 1761754199, 1761754199),
(35807, 'John 5:6', 'John', 5, 6, 'کله چې عیسی هغه سړی ولیده چې د زیاتې مودې راهیسې هلته پروت ؤ او په دې پوه شو چې هغه ناروغه دی، نو پوښتنه یې ترې وکړه: «ایا ته غواړې چې روغ شې؟»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_6.mp3', '', 1761754199, 1761754199),
(35808, 'John 5:7', 'John', 5, 7, 'هغه ناروغه سړي ځواب ورکړ: «ښاغلیه، کله چې اوبه وخوځیږي، نو زما سره څوک نشته چې ډنډ ته مې ورښکته کړي. کله چې زه حرکت وکړم نو بل کس زما نه مخکې ځان اوبو ته اچولی وي.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_7.mp3', '', 1761754199, 1761754199),
(35809, 'John 5:8', 'John', 5, 8, 'عیسی ورته وویل: «پاڅېږه، خپله بستره دې واخله او وګرځه.»', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_8.mp3', '', 1761754199, 1761754199),
(35810, 'John 5:9', 'John', 5, 9, 'هغه سړی سمدلاسه جوړ شو، خپله بستره یې واخیستله او روان شو. دا کار د سبت په ورځ وشو.', '', 'NT', 'afghan2023', 'afghan', 'afghan2023/nt/john5_verse_9.mp3', '', 1761754199, 1761754199);